    internal InnerMediaLiveConnectorPipelineHorizontalLayoutConfigurationFactory HorizontalLayoutConfigurationFactory { get; set; }

    internal InnerMediaLiveConnectorPipelineActiveSpeakerOnlyConfigurationFactory ActiveSpeakerOnlyConfigurationFactory { get; set; }

    internal InnerMediaLiveConnectorPipelineVerticalLayoutConfigurationFactory VerticalLayoutConfigurationFactory { get; set; }

    protected override Humidifier.Chime.MediaLiveConnectorPipelineTypes.GridViewConfiguration Create()
    {
        var gridViewConfigurationResult = CreateGridViewConfiguration();
        factoryAction?.Invoke(gridViewConfigurationResult);

        return gridViewConfigurationResult;
    }

    private Humidifier.Chime.MediaLiveConnectorPipelineTypes.GridViewConfiguration CreateGridViewConfiguration()
    {
        var gridViewConfigurationResult = new Humidifier.Chime.MediaLiveConnectorPipelineTypes.GridViewConfiguration();

        return gridViewConfigurationResult;
    }
    public override void CreateChildren(Humidifier.Chime.MediaLiveConnectorPipelineTypes.GridViewConfiguration result)
    {
        base.CreateChildren(result);

        result.PresenterOnlyConfiguration ??= PresenterOnlyConfigurationFactory?.Build();
        result.VideoAttribute ??= VideoAttributeFactory?.Build();
        result.HorizontalLayoutConfiguration ??= HorizontalLayoutConfigurationFactory?.Build();
        result.ActiveSpeakerOnlyConfiguration ??= ActiveSpeakerOnlyConfigurationFactory?.Build();
        result.VerticalLayoutConfiguration ??= VerticalLayoutConfigurationFactory?.Build();
    }

} // End Of Class

